    /// <summary>The user pressed a cross-tool button (only shown when the client declared the capability); the client fulfils it.</summary>
    public const string OverlayRequest = "overlay.request";

    /// <summary>Progress of a probe batch.</summary>
    public const string ProbeProgress = "probe.progress";

    /// <summary>A rule fired and all its actions completed.</summary>
    public const string RuleFired = "rule.fired";

    /// <summary>A sub-condition of a rule was satisfied.</summary>
    public const string RuleProgress = "rule.progress";

    /// <summary>A scene was loaded or unloaded, or the active scene changed.</summary>
    public const string SceneChanged = "scene.changed";

    /// <summary>A test run finished.</summary>
    public const string TestFinished = "test.finished";

    /// <summary>An in-game test finished.</summary>
    public const string TestResult = "test.result";

    /// <summary>An in-game test started.</summary>
    public const string TestStarted = "test.started";

    /// <summary>Live trace records, when a trace was started with <c>stream:true</c>.</summary>
    public const string TraceRecords = "trace.records";

    /// <summary>Batched value changes of watches. Also pullable with <c>watch.changes</c>.</summary>
    public const string WatchChanges = "watch.changes";
}
